  "ui.finalOnboarding.f54f5d4bcd": "La tua configurazione",
  "ui.finalOnboarding.7d2d594053": "Come vuoi usare Pixflow?",
  "ui.finalOnboarding.bdf73477f9": "Collega il tuo provider API",
  "ui.finalOnboarding.28edc3b8f2": "Collega il tuo abbonamento IA",
  "ui.finalOnboarding.f9573d1164": "Puoi iniziare a creare",
  "ui.finalOnboarding.45ddd1221b": "La modifica in WordPress e Gutenberg è gratuita. Non servono licenza o prova.",
  "ui.finalOnboarding.6072f06060": "Attiva la licenza per iniziare. Già attivata? La licenza apparirà qui.",
  "ui.finalOnboarding.ae83bc42b4": "Scegli ciò che preferisci. Puoi cambiarlo in qualsiasi momento nelle Impostazioni.",
  "ui.finalOnboarding.c9e2eb7fcb": "Usa una chiave API del tuo provider. Questa modalità non richiede il Bridge.",
  "ui.finalOnboarding.5add76d77c": "Il Bridge collega questo sito agli agenti IA sul tuo computer. L’utilizzo dell’IA avviene tramite l’account del tuo provider.",
  "ui.finalOnboarding.4813d31d25": "Usa lo spazio di lavoro WordPress senza collegare l’IA.",
  "ui.finalOnboarding.fbcd710247": "La connessione è configurata. Inizia con una domanda o descrivi cosa vuoi creare.",
  "ui.finalOnboarding.24fba6f166": "Collega un abbonamento IA",
  "ui.finalOnboarding.82d6b8daef": "Usa agenti supportati come Codex o OpenCode tramite Pixflow Design Bridge.",
  "ui.finalOnboarding.894f66ba11": "Usa una chiave API",
  "ui.finalOnboarding.e76c3bfd0e": "Collegati direttamente al tuo provider. L’utilizzo dell’API viene fatturato separatamente.",
  "ui.finalOnboarding.1be451ef72": "Continua senza IA",
  "ui.finalOnboarding.88e6e83b86": "Usa lo spazio di lavoro WordPress. Aggiungi l’IA più tardi, se vuoi.",
  "ui.finalOnboarding.105e56e56f": "Perché scegliere la CLI locale?",
  "ui.finalOnboarding.5df057fcd7": "L’utilizzo dell’API viene fatturato separatamente",
  "ui.finalOnboarding.44e30ed15f": "BYOK richiede una chiave API. Il provider IA addebita l’uso dell’API separatamente dall’abbonamento CLI, quindi può comportare costi aggiuntivi anziché consumare i limiti inclusi o settimanali dell’account CLI.",
