  "ui.mediaStarter.image1.title": "Ritratto editoriale",
  "ui.mediaStarter.image1.tag": "Ritratto",
  "ui.mediaStarter.image1.prompt": "Un ritratto editoriale ravvicinato di una persona verso i trent’anni che lavora nella direzione creativa, luce naturale morbida da alte finestre di studio, palette neutra calda (crema, tortora, nero tenue), scatto a 85 mm f/1.8 con ridotta profondità di campo, sguardo nitido in camera, lieve grana analogica, aspetto senza trucco.",
  "ui.mediaStarter.image2.title": "Immagine principale del prodotto",
  "ui.mediaStarter.image2.tag": "E-commerce",
  "ui.mediaStarter.image2.prompt": "Una foto principale di prodotto di alta gamma: una sola tazza da caffè in ceramica opaca su carta color crema caldo. Luce di contorno netta dall’alto a sinistra, ombra morbida e allungata verso il basso a destra, un filo di vapore dalla tazza. Taglio quadrato, composizione centrata, spazio sopra per un titolo, nessun oggetto di scena né mani.",
  "ui.mediaStarter.image3.title": "Illustrazione piatta",
  "ui.mediaStarter.image3.tag": "Illustrazione",
  "ui.mediaStarter.image3.prompt": "Un’illustrazione vettoriale piatta di un accogliente angolo lettura vicino a una finestra piovosa: forme geometriche, palette sobria di cinque colori (crema, terracotta, verde petrolio scuro, terra di Siena bruciata, nero tenue), sottili accenti di linea da 1.5px, senza sfumature o texture, ombre morbide solo sulla poltrona in primo piano.",
  "ui.mediaStarter.video1.title": "Presentazione del prodotto",
  "ui.mediaStarter.video1.tag": "Cinematografico",
  "ui.mediaStarter.video1.prompt": "Una presentazione di prodotto di 5 secondi: un flacone minimalista di skincare di alta gamma su pietra color crema pulita, luce laterale morbida da sinistra, lento avvicinamento della camera, lieve spostamento del fuoco dal tappo all’etichetta, movimento sobrio, senza testi sovrapposti né persone.",
  "ui.mediaStarter.video2.title": "Lanterna in primo piano",
  "ui.mediaStarter.video2.tag": "Atmosfera",
  "ui.mediaStarter.video2.prompt": "Un primo piano cinematografico di 6 secondi di una giovane donna che tiene una lanterna di carta luminosa in una pineta nebbiosa all’ora dorata. Ridotta profondità di campo sugli occhi, dolce carrello in avanti, particelle nel fascio di luce calda, nessun dialogo, solo suoni della foresta.",
  "ui.mediaStarter.video3.title": "Derapata tra i neon",
  "ui.mediaStarter.video3.tag": "Azione",
  "ui.mediaStarter.video3.prompt": "Una ripresa di inseguimento di una corsa urbana di 5 secondi, di notte, in un vicolo cyberpunk di Hong Kong illuminato al neon. Camera bassa che segue un’auto sportiva nera opaca in derapata in una curva stretta, ruote sfocate dal movimento, riflessi ottici delle insegne, asfalto bagnato che riflette le luci, nessun testo.",
  "ui.mediaStarter.hyperframes1.title": "Rivelazione con lente",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Crea una composizione di 5 secondi con una sola riga di testo grande in grassetto su una tela pulita. Anima una lente d’ingrandimento rotonda da sinistra a destra lungo la riga, con una lieve rifrazione che deformi le lettere al passaggio. Usa HyperFrames html-in-canvas: cattura il DOM del testo e applica sopra uno shader lente con un passaggio in stile vfx-liquid-glass. CSS puro per il testo; il vetro è un livello WebGL.",
  "ui.mediaStarter.hyperframes2.title": "Scena terminale CRT",
  "ui.mediaStarter.hyperframes2.tag": "VFX vintage",
  "ui.mediaStarter.hyperframes2.prompt": "Crea una composizione schermo CRT: tela scura, testo terminale monospaziato che digita `npx hyperframes init my-video`, poi invoca `claude` con il prompt «Aggiungi un effetto CRT con HTML-in-canvas». Applica una lieve curvatura convessa, linee di scansione, leggera aberrazione cromatica e un tenue bagliore al fosforo sopra il DOM attivo tramite html-in-canvas. Il testo resta vero CSS, nitido prima del passaggio shader.",
  "ui.mediaStarter.hyperframes3.title": "Scomposizione glitch",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Crea una composizione di 6 secondi con titolo principale e sottotitolo di una riga su tela scura, poi un forte glitch digitale: separazione dei canali RGB, bande di spostamento orizzontale, breve scatto dei fotogrammi e ripristino pulito finale. Cattura il DOM attivo tramite html-in-canvas e applica il glitch sopra, così il testo resta vero CSS sotto lo shader.",
  "ui.mediaStarter.audio1.title": "Voce fuori campo del brand",
  "ui.mediaStarter.audio1.tag": "Parlato",
  "ui.mediaStarter.audio1.prompt": "Una voce narrante calda di 30 secondi per un video di lancio: sicura ma colloquiale, ritmo medio, breve pausa dopo il nome del brand. Testo: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' In inglese, con accento nordamericano neutro.",
  "ui.mediaStarter.audio2.title": "Narrazione introduttiva",
  "ui.mediaStarter.audio2.tag": "Parlato",
  "ui.mediaStarter.audio2.prompt": "Una narrazione introduttiva amichevole di 20 secondi per il primo avvio di un’app mobile. Tono rassicurante e sorridente, abbastanza lento da risultare attento senza sembrare recitato. Testo: «Benvenuto in Loop. Prepariamo il tuo spazio: tre domande veloci e sei dentro. Potrai cambiare tutto più tardi».",
  "ui.mediaStarter.audio3.title": "Lettura di un racconto",
  "ui.mediaStarter.audio3.tag": "Parlato",
  "ui.mediaStarter.audio3.prompt": "Una lettura cinematografica di 45 secondi di un brano iniziale. Voce bassa e misurata, respiro tra le frasi, intimità da microfono ravvicinato. Testo: «La città dorme a pezzi. Un’insegna al neon tremola sopra il bancone del ramen. Dall’altra parte del viale, una finestra brilla: l’unica ancora accesa da questo lato della mezzanotte».",
  "ui.finalWorkspace.72ed7e2a11": "Esempi di famiglie di caratteri",
